// Generate the project-local OpenCode **v2** plugin that makes the Design Studio
// harness run automatically inside agent sessions.
//
// Why a generated file: the harness (craft rules + the mandatory verification
// protocol) currently only reaches the model when the panel composes a prompt.
// A project plugin loaded by OpenCode runs on every turn, so the rules and the
// verification mandate hold even for edits the user starts directly in chat.
//
// The plugin API below was verified against the OpenChamber-bundled OpenCode
// v2.0.27 (`.opencode/plugin/*.ts`, default export `{ id, setup(ctx) }`,
// `ctx.session.hook("context", …)` and `ctx.tool.hook("execute.after", …)`).
// Do not change these shapes without re-verifying against that binary.
//
// Side effects of writing into a project (deliberate, and the caller's choice):
//  · Creating `.opencode/plugin/` makes OpenCode discover and load the file into
//    every session for that project. This is the whole point, but it IS a change
//    to how the project behaves; the file is marked and never silently clobbered.
//  · The generated file imports nothing and adds no dependency, so no
//    `node_modules` install and no package.json change are needed. If the project
//    keeps `.opencode/` out of git, the user should add it to `.gitignore`.
import { promises as fs } from 'node:fs';
import path from 'node:path';

import { DESIGN_WORKSPACE_NOTE, VERIFY_MANDATE, harnessRulesText } from '../shared/harness-text.ts';

/** Path of the generated plugin, relative to the project root. */
export const HARNESS_PLUGIN_REL = '.opencode/plugin/design-studio-harness.ts';

/** Stable plugin id. */
export const HARNESS_PLUGIN_ID = 'design-studio-harness';

/**
 * The banner that marks a file as ours. A file without it is never overwritten,
 * so a hand-written `.opencode/plugin/design-studio-harness.ts` survives.
 */
export const HARNESS_MARKER = 'design-studio harness — generated, do not edit';

/** Built-in tools whose completion means a source file changed. */
export const EDIT_TOOLS = ['edit', 'write', 'patch', 'multiedit', 'apply_patch'];

export type WriteHarnessResult = {
  /** Path written, relative to the project root. */
  path: string;
  /** True when the file did not exist before this call. */
  created: boolean;
  /** True when an existing generated file was rewritten. */
  updated: boolean;
  /** True when bytes on disk changed (false when already up to date). */
  changed: boolean;
};

/** The self-contained plugin source, with the harness text inlined verbatim. */
export function harnessPluginSource(): string {
  const rules = harnessRulesText();
  const nudge = [
    'A file was just edited in this Design Studio session.',
    'Before continuing: verify the change with the browser tool at every viewport (mobile, tablet, desktop, wide),',
    'fix every P0 before starting a new gate tier, and do not mark the work done while any P0 remains.',
    'If a finding you already fixed reappears, stop and hand back with both states instead of looping.',
    VERIFY_MANDATE,
  ].join(' ');
  const line = (value: string): string => JSON.stringify(value);

  return [
    `// ${HARNESS_MARKER}`,
    '//',
    '// Generated by the OpenChamber Design Studio extension. Rewritten in place when a',
    '// design session starts; any manual edit is lost on the next write. Change the',
    '// rules in the extension (shared/harness-text.ts), not here.',
    '//',
    '// Side effects of this file living in the project:',
    '//  · OpenCode discovers `.opencode/plugin/*.ts` and loads it into every session',
    '//    for this project automatically.',
    '//  · It imports nothing, so it adds no',
    '//    dependency and needs no `node_modules` install. If `.opencode/` is not',
    '//    tracked, add it to `.gitignore`.',
    '//',
    '// What it does:',
    '//  · Pushes the Design Studio harness rules into every model turn (identity,',
    '//    design-system authority, craft rules, verification protocol, mandate).',
    '//  · Flags the session after a completed edit/write/patch so the next turn',
    '//    carries an explicit verification nudge.',
    '//  · Preserves the selected project workspace; never creates or moves sessions.',
    '',
    `const HARNESS_RULES = ${line(rules)}`,
    '',
    `const VERIFY_NUDGE = ${line(nudge)}`,
    '',
    `const WORKSPACE_NOTE = ${line(DESIGN_WORKSPACE_NOTE)}`,
    '',
    `const EDIT_TOOLS = new Set(${JSON.stringify(EDIT_TOOLS)})`,
    '',
    'export default {',
    `  id: ${line(HARNESS_PLUGIN_ID)},`,
    '  async setup(ctx) {',
    '    // Sessions share one plugin instance, so track nudges per session id.',
    '    const pending = new Set()',
    '',
    '    await ctx.session.hook("context", async (event) => {',
    '      event.system.push({ type: "text", text: WORKSPACE_NOTE })',
    '      event.system.push({ type: "text", text: HARNESS_RULES })',
    '      if (pending.has(event.sessionID)) {',
    '        pending.delete(event.sessionID)',
    '        event.system.push({ type: "text", text: VERIFY_NUDGE })',
    '      }',
    '    })',
    '',
    '    await ctx.tool.hook("execute.after", (event) => {',
    '      if (event.status !== "completed") return',
    '      if (!EDIT_TOOLS.has(event.tool)) return',
    '      pending.add(event.sessionID)',
    '    })',
    '  },',
    '}',
    '',
  ].join('\n');
}

/**
 * Write (or refresh) the harness plugin in a project.
 *
 * Idempotent: a second call with identical rules reports `changed:false` and
 * touches nothing. Safe against user work: an existing file that lacks the
 * generated marker is refused, never overwritten. The write is confined to the
 * project directory.
 */
export async function writeHarnessPlugin(projectDir: string): Promise<WriteHarnessResult> {
  const rootAbs = path.resolve(projectDir);
  const abs = path.resolve(rootAbs, HARNESS_PLUGIN_REL);
  if (abs !== rootAbs && !abs.startsWith(rootAbs + path.sep)) {
    throw new Error('path outside project');
  }

  const source = harnessPluginSource();

  let existing: string | null = null;
  try {
    existing = await fs.readFile(abs, 'utf8');
  } catch {
    existing = null;
  }

  if (existing !== null) {
    if (!existing.includes(HARNESS_MARKER)) {
      throw new Error(`refusing to overwrite ${HARNESS_PLUGIN_REL}: it was not generated by Design Studio`);
    }
    if (existing === source) {
      return { path: HARNESS_PLUGIN_REL, created: false, updated: false, changed: false };
    }
    await fs.writeFile(abs, source, 'utf8');
    return { path: HARNESS_PLUGIN_REL, created: false, updated: true, changed: true };
  }

  await fs.mkdir(path.dirname(abs), { recursive: true });
  await fs.writeFile(abs, source, 'utf8');
  return { path: HARNESS_PLUGIN_REL, created: true, updated: false, changed: true };
}
